/* MACD + KDJ 双金叉共振（P.p1 共振窗口 / P.p2 KDJ 周期） */
function mGold(i){
  var a = MACD(i), b = MACD(i - 1);
  return a.dif > a.dea && b.dif <= b.dea;
}
function jGold(i){
  var a = KDJ(i, P.p2), b = KDJ(i - 1, P.p2);
  return a.k > a.d && b.k <= b.d;
}
function recent(i, fn){
  for (var k = 0; k < P.p1; k++){ if (fn(i - k)) return true; }
  return false;
}
function buy(i){
  return recent(i, mGold) && recent(i, jGold);
}
function sell(i, pos){
  var a = MACD(i), b = MACD(i - 1);
  var c = KDJ(i, P.p2), e = KDJ(i - 1, P.p2);
  return (a.dif < a.dea && b.dif >= b.dea) || (c.k < c.d && e.k >= e.d);
}
